const candidate = $json;
function invalid(code, message, missing) {
  return [{ json: { _valid: 'false', error_code: code, error_message: message, missing_fields: missing || [] } }];
}
if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
  return invalid('INVALID_HANDOFF_INPUT', 'Input is not a JSON object.', ['root']);
}
const requiredTop = ['status_kind', 'result_type', 'payload'];
const missingTop = requiredTop.filter(k => !(k in candidate));
if (missingTop.length) return invalid('INVALID_HANDOFF_INPUT', 'Required plan fields are missing.', missingTop);
const payload = candidate.payload;
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return invalid('INVALID_HANDOFF_INPUT', 'payload must be an object.', ['payload']);
const requiredPayload = ['tenant_id','thread_id','execution_id','trigger_message_id','idempotency_key','plan_id','goal','primary_intent','steps','dispatcher_input'];
const missingPayload = requiredPayload.filter(k => !(k in payload)).map(k => `payload.${k}`);
if (missingPayload.length) return invalid('INVALID_HANDOFF_INPUT', 'Required plan payload fields are missing.', missingPayload);
if (candidate.status_kind !== 'success') return invalid('INVALID_HANDOFF_INPUT', 'status_kind must be success.', ['status_kind']);
if (candidate.result_type !== 'plan') return invalid('INVALID_HANDOFF_INPUT', 'result_type must be plan.', ['result_type']);
if (!Array.isArray(payload.steps) || !payload.steps.length) return invalid('INVALID_PLAN', 'steps must be a non-empty array.', ['payload.steps']);
const guard = payload.dispatcher_input || {};
if (guard.dispatch_allowed !== true) return invalid('INVALID_PLAN', 'dispatch_allowed must be true.', ['payload.dispatcher_input.dispatch_allowed']);
if (guard.module_execution_started !== false) return invalid('INVALID_PLAN', 'module_execution_started must be false.', ['payload.dispatcher_input.module_execution_started']);
if (guard.response_generation_allowed !== false) return invalid('INVALID_PLAN', 'response_generation_allowed must be false.', ['payload.dispatcher_input.response_generation_allowed']);
if (guard.domain_writes_performed !== false) return invalid('INVALID_PLAN', 'domain_writes_performed must be false.', ['payload.dispatcher_input.domain_writes_performed']);
for (let i = 0; i < payload.steps.length; i++) {
  const step = payload.steps[i];
  const req = ['step_id','module_name','purpose','inputs','depends_on','execution_mode','expected_outputs','replan_if','failure_policy','status'];
  const miss = req.filter(k => !(k in step)).map(k => `payload.steps[${i}].${k}`);
  if (miss.length) return invalid('INVALID_PLAN', `Step ${i} is missing required fields.`, miss);
  if (step.status !== 'pending') return invalid('INVALID_PLAN', `Step ${i} status must be pending.`, [`payload.steps[${i}].status`]);
  if (!['sequential','parallel'].includes(step.execution_mode)) return invalid('INVALID_PLAN', `Step ${i} execution_mode invalid.`, [`payload.steps[${i}].execution_mode`]);
}
return [{ json: { _valid: 'true', _normalized_plan_result: { status_kind: 'success', result_type: 'plan', module_name: candidate.module_name || 'plan_generation', payload: payload } } }];

const row = $json;
const source = $('DI_Extract_Dispatch_Input').first().json;
if (!row || !row.execution_id) {
  return [{ json: { _context_ready: 'false', error_code: 'CONTEXT_MISMATCH', error_message: 'Execution context row was not found or is incomplete.', missing_fields: ['execution_context'] } }];
}
for (const field of ['execution_id','tenant_id','thread_id']) {
  if (String(row[field] || '') !== String(source[field] || '')) {
    return [{ json: { _context_ready: 'false', error_code: 'CONTEXT_MISMATCH', error_message: `${field} does not match canonical execution context.`, missing_fields: [field] } }];
  }
}
if (String(row.status || '') !== 'initialized') {
  return [{ json: { _context_ready: 'false', error_code: 'CONTEXT_MISMATCH', error_message: 'Execution context is not initialized.', missing_fields: ['status'] } }];
}
return [{ json: { _context_ready: 'true', warnings: [] } }];

return [{ json: { module_registry: [
  { module_name: 'task_module', module_type: 'executor', capabilities: ['create_task','list_tasks','update_task','complete_task','delete_task'] },
  { module_name: 'reminder_module', module_type: 'executor', capabilities: ['create_reminder','list_reminders','update_reminder','cancel_reminder'] },
  { module_name: 'memory_module', module_type: 'executor', capabilities: ['store_memory','search_memory'] },
  { module_name: 'improvement_module', module_type: 'executor', capabilities: ['capture_feedback'] },
  { module_name: 'watcher_module_basic', module_type: 'observer', capabilities: ['produce_observation'] }
] } }];

const verify = $('DI_Verify_Context_Match').first().json;
if (verify._context_ready === 'false') {
  return [{ json: verify }];
}
const source = $('DI_Extract_Dispatch_Input').first().json;
const registry = ($json.module_registry || []);
const registryMap = Object.fromEntries(registry.map(item => [item.module_name, item]));
const stepIds = new Set((source.steps || []).map(step => step.step_id));
const readyParallel = [];
const readySequential = [];
for (const step of (source.steps || [])) {
  if (!registryMap[step.module_name]) {
    return [{ json: { _context_ready: 'false', error_code: 'UNKNOWN_MODULE', error_message: `Module ${step.module_name} is not present in the capability registry.`, missing_fields: [`module_registry.${step.module_name}`] } }];
  }
  const unknownDeps = (step.depends_on || []).filter(dep => !stepIds.has(dep));
  if (unknownDeps.length) {
    return [{ json: { _context_ready: 'false', error_code: 'INVALID_PLAN', error_message: `Step ${step.step_id} depends on unknown steps.`, missing_fields: unknownDeps.map(dep => `depends_on.${dep}`) } }];
  }
  const request = {
    execution_context_id: source.execution_id,
    thread_id: source.thread_id,
    step_id: step.step_id,
    module_name: step.module_name,
    purpose: step.purpose,
    inputs: step.inputs || {},
    idempotency_key: `${source.idempotency_key}:${step.step_id}:dispatch:v1`
  };
  const item = { step_id: step.step_id, execution_mode: step.execution_mode, depends_on: step.depends_on || [], module_request: request };
  if (step.execution_mode === 'parallel' && (!step.depends_on || !step.depends_on.length)) readyParallel.push(item); else readySequential.push(item);
}
const groups = [];
if (readyParallel.length) {
  groups.push({ group_id: 'group:parallel:001', execution_mode: 'parallel', step_ids: readyParallel.map(x => x.step_id), module_requests: readyParallel.map(x => x.module_request) });
}
readySequential.forEach((item, index) => {
  groups.push({ group_id: `group:sequential:${String(index + 1).padStart(3,'0')}`, execution_mode: 'sequential', step_ids: [item.step_id], module_requests: [item.module_request] });
});
return [{ json: { _context_ready: 'true', dispatch_input: source, ready_groups: groups, warnings: source.warnings || [] } }];

const data = $json;
const source = data.dispatch_input;
const dispatchId = `dispatch:${source.plan_id}:v1`;
return [{ json: {
  status_kind: 'success',
  result_type: 'dispatch',
  module_name: 'dispatcher',
  payload: {
    tenant_id: String(source.tenant_id),
    thread_id: String(source.thread_id),
    execution_id: String(source.execution_id),
    plan_id: String(source.plan_id),
    dispatch_id: dispatchId,
    allowed_next_stage: 'WF-ME-01',
    ready_groups: data.ready_groups || [],
    dispatch_guard: {
      dispatch_allowed: true,
      module_execution_started: false,
      response_generation_allowed: false,
      domain_writes_performed: false
    },
    warnings: Array.isArray(data.warnings) ? data.warnings : []
  }
}}];

return [{ json: {
  status_kind: 'failed',
  result_type: 'error',
  module_name: 'dispatcher',
  error: {
    code: $json.error_code || 'INVALID_PLAN',
    message: $json.error_message || 'Dispatcher error.',
    missing_fields: Array.isArray($json.missing_fields) ? $json.missing_fields : []
  }
}}];
